const nextSubscriptionSlot = `-- name: NextSubscriptionSlot :one
SELECT COALESCE(max(slot), 0)::int + 1 AS next_slot
FROM subscriptions WHERE user_id = $1
`

// The first free slot on the target, so moved subscriptions do not collide with
// the unique constraint on (user_id, slot).
func (q *Queries) NextSubscriptionSlot(ctx context.Context, userID pgtype.UUID) (int32, error) {
	row := q.db.QueryRow(ctx, nextSubscriptionSlot, userID)
	var next_slot int32
	err := row.Scan(&next_slot)
	return next_slot, err
}

const revokeMergedCustomerSessions = `-- name: RevokeMergedCustomerSessions :many
UPDATE customer_sessions
SET revoked_at = now(), revoked_reason = 'account_merged'
WHERE user_id = $1 AND revoked_at IS NULL
RETURNING 1 AS done
`

// Every session of the absorbed account ends. The person signs in again and
// lands on the survivor, which now holds their sign-in methods.
func (q *Queries) RevokeMergedCustomerSessions(ctx context.Context, source pgtype.UUID) ([]int32, error) {
	rows, err := q.db.Query(ctx, revokeMergedCustomerSessions, source)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []int32{}
	for rows.Next() {
		var done int32
		if err := rows.Scan(&done); err != nil {
			return nil, err
		}
		items = append(items, done)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
